// Retire the service worker previously generated by gatsby-plugin-offline.
// Keeping this small replacement at /sw.js lets existing installations update,
// clear their stale caches, and then unregister themselves.
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', event => {
  event.waitUntil(
    Promise.all([
      self.registration.unregister(),
      caches.keys().then(keys => Promise.all(keys.map(key => caches.delete(key)))),
    ]).then(() =>
      self.clients.matchAll({ type: 'window' }).then(clients => {
        clients.forEach(client => client.navigate(client.url));
      }),
    ),
  );
});
